const express = require('express');
const cron = require('node-cron');
const { checkApiKey } = require('../auth');

const router = express.Router();
const activeCronTasks = new Map();

router.put('/api/cron-jobs/:jobId', checkApiKey, (req, res) => {
  const { jobId } = req.params;
  const { cronExpression, webhookUrl } = req.body;

  const existingTask = activeCronTasks.get(jobId);
  if (!existingTask) return res.status(404).json({ error: 'Task not found' });

  if (existingTask.tenantId !== req.apiKeyData.tenantId) {
    return res.status(403).json({ error: 'Forbidden: access denied to specified cron job' });
  }

  existingTask.task.stop();
  const newTask = cron.schedule(cronExpression, async () => {
    await fetch(webhookUrl, { method: 'POST', body: JSON.stringify({ triggeredAt: Date.now() }) });
  });

  activeCronTasks.set(jobId, { ...existingTask, task: newTask, webhookUrl });
  res.json({ updated: true, jobId });
});
